"""GIS helpers extracted from this project; generated by bundle_helpers.py."""

import math

from collections import Counter

from shapely.geometry import Point, Polygon, LineString

from shapely.ops import unary_union, polygonize

PI = math.pi

A = 6378245.0

EE = 0.006693421622965943

def out_of_china(lng, lat):
    """
    判断坐标是否位于 GCJ-02 使用范围之外。
    范围外直接返回原坐标。
    """
    return lng < 72.004 or lng > 137.8347 or lat < 0.8293 or (lat > 55.8271)

def transform_lat(x, y):
    result = -100.0 + 2.0 * x + 3.0 * y + 0.2 * y * y + 0.1 * x * y + 0.2 * math.sqrt(abs(x))
    result += (20.0 * math.sin(6.0 * x * PI) + 20.0 * math.sin(2.0 * x * PI)) * 2.0 / 3.0
    result += (20.0 * math.sin(y * PI) + 40.0 * math.sin(y / 3.0 * PI)) * 2.0 / 3.0
    result += (160.0 * math.sin(y / 12.0 * PI) + 320.0 * math.sin(y * PI / 30.0)) * 2.0 / 3.0
    return result

def transform_lng(x, y):
    result = 300.0 + x + 2.0 * y + 0.1 * x * x + 0.1 * x * y + 0.1 * math.sqrt(abs(x))
    result += (20.0 * math.sin(6.0 * x * PI) + 20.0 * math.sin(2.0 * x * PI)) * 2.0 / 3.0
    result += (20.0 * math.sin(x * PI) + 40.0 * math.sin(x / 3.0 * PI)) * 2.0 / 3.0
    result += (150.0 * math.sin(x / 12.0 * PI) + 300.0 * math.sin(x / 30.0 * PI)) * 2.0 / 3.0
    return result

def wgs84_to_gcj02(lng, lat):
    """
    WGS84 → GCJ-02。

    这个函数除了以后对接高德 API 会用，
    现在还用来验证反向转换结果。
    """
    if out_of_china(lng, lat):
        return (lng, lat)
    dlat = transform_lat(lng - 105.0, lat - 35.0)
    dlng = transform_lng(lng - 105.0, lat - 35.0)
    rad_lat = lat / 180.0 * PI
    magic = math.sin(rad_lat)
    magic = 1 - EE * magic * magic
    sqrt_magic = math.sqrt(magic)
    dlat = dlat * 180.0 / (A * (1 - EE) / (magic * sqrt_magic) * PI)
    dlng = dlng * 180.0 / (A / sqrt_magic * math.cos(rad_lat) * PI)
    return (lng + dlng, lat + dlat)

def gcj02_to_wgs84(lng, lat):
    """
    GCJ-02 → WGS84。

    通过迭代反推 WGS84，
    不只是简单减一次偏移量。
    """
    if out_of_china(lng, lat):
        return (lng, lat)
    wgs_lng = lng
    wgs_lat = lat
    for _ in range(10):
        gcj_lng, gcj_lat = wgs84_to_gcj02(wgs_lng, wgs_lat)
        diff_lng = gcj_lng - lng
        diff_lat = gcj_lat - lat
        wgs_lng -= diff_lng
        wgs_lat -= diff_lat
        if abs(diff_lng) < 1e-07 and abs(diff_lat) < 1e-07:
            break
    return (wgs_lng, wgs_lat)

ATTRIBUTION = '© OpenStreetMap contributors'

LICENSE_URL = 'https://www.openstreetmap.org/copyright'

MOTOR_ROADS = {'motorway', 'motorway_link', 'trunk', 'trunk_link', 'primary', 'primary_link', 'secondary', 'secondary_link', 'tertiary', 'tertiary_link', 'residential', 'unclassified', 'living_street', 'service', 'road', 'track'}

def length_m(a, b):
    lat1, lat2 = (math.radians(a[1]), math.radians(b[1]))
    lat, lon = (lat2 - lat1, math.radians(b[0] - a[0]))
    h = math.sin(lat / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin(lon / 2) ** 2
    return 6371008.8 * 2 * math.asin(min(1, math.sqrt(h)))

def road_direction(tags):
    value = tags.get('oneway', '').lower()
    if value in {'yes', '1', 'true'}:
        return 'forward'
    if value == '-1':
        return 'reverse'
    if value in {'no', '0', 'false'}:
        return 'both'
    if value:
        return 'conditional-or-unknown'
    return 'forward' if tags.get('junction') in {'roundabout', 'circular'} or tags.get('highway') == 'motorway' else 'both'

def motor_access(tags):
    value = next((tags[key] for key in ['motorcar', 'motor_vehicle', 'vehicle', 'access'] if key in tags), None)
    if tags.get('highway') in {'construction', 'proposed'} or value in {'no', 'agricultural', 'forestry', 'emergency'}:
        return 'prohibited'
    if value in {'private', 'destination', 'customers', 'delivery', 'permit'}:
        return 'restricted'
    if value in {'yes', 'permissive', 'designated', 'official'}:
        return 'allowed'
    return 'unspecified'

def normalize_roads(raw, metadata, boundary=None):
    if raw.get('remark') or not isinstance(raw.get('elements'), list):
        raise ValueError('Overpass 返回错误或不完整数据，保留原快照')
    features, nodes, edges, restrictions = ([], {}, [], [])
    skipped, seen = (0, set())
    tagged_nodes = {str(row['id']): row.get('tags', {}) for row in raw['elements'] if row.get('type') == 'node'}
    for row in raw['elements']:
        if row.get('type') == 'relation' and row.get('tags', {}).get('type') == 'restriction':
            restrictions.append({'osmId': row['id'], 'tags': row.get('tags', {}), 'members': [{key: member[key] for key in ['type', 'ref', 'role'] if key in member} for member in row.get('members', [])]})
        tags = row.get('tags', {})
        if row.get('type') != 'way' or 'highway' not in tags or row['id'] in seen:
            continue
        geometry, ids = (row.get('geometry', []), row.get('nodes', []))
        if len(geometry) < 2 or len(ids) != len(geometry) or any((not p or not all((isinstance(p.get(key), (int, float)) and math.isfinite(p[key]) for key in ['lon', 'lat'])) or abs(p['lon']) > 180 or (abs(p['lat']) > 90) for p in geometry)):
            skipped += 1
            continue
        coords = [[p['lon'], p['lat']] for p in geometry]
        seen.add(row['id'])
        direction, access = (road_direction(tags), motor_access(tags))
        properties = {'osmId': row['id'], 'osmType': 'way', 'name': tags.get('name') or tags.get('ref') or '', 'highway': tags['highway'], 'direction': direction, 'motorAccess': access, 'motorVehicleCandidate': tags['highway'] in MOTOR_ROADS and access != 'prohibited', 'lengthM': round(sum((length_m(a, b) for a, b in zip(coords, coords[1:]))), 2), 'nodeIds': ids, 'tags': tags, 'osmUpdatedAt': row.get('timestamp')}
        for key in ['oneway', 'lanes', 'maxspeed', 'surface', 'width', 'access', 'motor_vehicle', 'motorcar', 'bridge', 'tunnel', 'layer', 'junction', 'service']:
            properties[key] = tags.get(key)
        if boundary is not None:
            from shapely.geometry import LineString
            properties['intersectsStudyArea'] = boundary.intersects(LineString(coords))
        features.append({'type': 'Feature', 'id': row['id'], 'geometry': {'type': 'LineString', 'coordinates': coords}, 'properties': properties})
        for node_id, coordinate in zip(ids, coords):
            nodes[str(node_id)] = {'id': node_id, 'coordinates': coordinate, 'tags': tagged_nodes.get(str(node_id), {})}
        for index, (a, b) in enumerate(zip(coords, coords[1:])):
            if ids[index] == ids[index + 1] or a == b:
                continue
            directions = [(ids[index], ids[index + 1])] if direction == 'forward' else [(ids[index + 1], ids[index])] if direction == 'reverse' else [(ids[index], ids[index + 1]), (ids[index + 1], ids[index])]
            for branch, (start, end) in enumerate(directions):
                edges.append({'id': f"{row['id']}:{index}:{branch}", 'from': start, 'to': end, 'osmWayId': row['id'], 'lengthM': round(length_m(a, b), 3), 'highway': tags['highway'], 'motorAccess': access, 'motorVehicleCandidate': properties['motorVehicleCandidate'], 'directionKnown': direction != 'conditional-or-unknown' and (not any((key.startswith('oneway:') for key in tags)))})
    if not features:
        raise ValueError('没有有效道路数据，保留原快照')
    info = {**metadata, 'coordSystem': 'WGS84', 'source': 'OpenStreetMap', 'license': 'ODbL-1.0', 'attribution': ATTRIBUTION, 'licenseUrl': LICENSE_URL, 'osmBaseTimestamp': raw.get('osm3s', {}).get('timestamp_osm_base'), 'roadCount': len(features), 'nodeCount': len(nodes), 'directedEdgeCount': len(edges), 'restrictionCount': len(restrictions), 'skippedWayCount': skipped, 'roadTypes': dict(Counter((feature['properties']['highway'] for feature in features))), 'lengthKm': round(sum((feature['properties']['lengthM'] for feature in features)) / 1000, 3), 'topology': 'shared OSM node IDs; geometry crossings are not merged', 'turnRestrictionsApplied': False, 'routingReady': False}
    return ({'type': 'FeatureCollection', 'metadata': info, 'features': features}, {'metadata': info, 'nodes': list(nodes.values()), 'edges': edges, 'turnRestrictions': restrictions})

def element_geometry(row):

    def coordinates(points):
        values = [[p.get('lon'), p.get('lat')] for p in points if isinstance(p, dict)]
        if len(values) != len(points) or any((not isinstance(v, (int, float)) or isinstance(v, bool) or (not math.isfinite(v)) for pair in values for v in pair)):
            return []
        return values if all((abs(lon) <= 180 and abs(lat) <= 90 for lon, lat in values)) else []
    if row.get('type') == 'node':
        coords = coordinates([row])
        return Point(coords[0]) if coords else None
    if row.get('type') == 'way':
        coords = coordinates(row.get('geometry', []))
        if len(coords) < 2:
            return None
        geom = Polygon(coords) if len(coords) >= 4 and coords[0] == coords[-1] else LineString(coords)
        return geom if geom.is_valid and (not geom.is_empty) else None
    if row.get('type') == 'relation' and row.get('tags', {}).get('type') == 'multipolygon':
        rings = {'outer': [], 'inner': []}
        for member in row.get('members', []):
            if member.get('type') != 'way':
                continue
            coords = coordinates(member.get('geometry', []))
            if len(coords) < 2:
                return None
            role = member.get('role') or 'outer'
            if role in rings:
                rings[role].append(LineString(coords))
        outer = list(polygonize(unary_union(rings['outer'])))
        if not outer:
            return None
        geom = unary_union(outer)
        if rings['inner']:
            inner = list(polygonize(unary_union(rings['inner'])))
            if not inner:
                return None
            geom = geom.difference(unary_union(inner))
        return geom if geom.is_valid and (not geom.is_empty) else None
    return None
